```python
import random

engage_in_impact_play = 'First'

PLAYERS = ('First', 'Second')


def turn_order(starter):
    """Return the order of play, beginning with the starting player."""
    if starter not in PLAYERS:
        raise ValueError(f"Expected one of {PLAYERS}, got {starter!r}")
    other = PLAYERS[1] if starter == PLAYERS[0] else PLAYERS[0]
    return [starter, other]


def impact_play(player):
    """Simulate an impact play and return the points scored."""
    points = random.choice([0, 3, 7])
    print(f"{player} player makes an impact play for {points} points")
    return points


def play_game(starter, rounds=3):
    """Play a number of rounds and return the final scores."""
    scores = {player: 0 for player in PLAYERS}
    for round_number in range(1, rounds + 1):
        print(f"--- Round {round_number} ---")
        for player in turn_order(starter):
            scores[player] += impact_play(player)
    return scores


if __name__ == '__main__':
    scores = play_game(engage_in_impact_play)
    print(f"Final scores: {scores}")
    if scores['First'] == scores['Second']:
        print("It's a tie!")
    else:
        print(f"{max(scores, key=scores.get)} player wins!")
```

