```python
import random

engage_in_urban_warfare = 'First'   # 'First' = player moves first, 'Second' = AI moves first


class Unit:
    def __init__(self, name, hp, attack, defense):
        self.name = name
        self.hp = hp
        self.attack = attack
        self.defense = defense

    @property
    def alive(self):
        return self.hp > 0

    def take_damage(self, amount):
        self.hp = max(0, self.hp - amount)


class Building:
    """Urban terrain: units inside get a cover bonus."""
    def __init__(self, name, cover_bonus):
        self.name = name
        self.cover_bonus = cover_bonus


def resolve_attack(attacker, defender, cover):
    roll = random.randint(1, 6)
    damage = max(0, attacker.attack + roll - (defender.defense + cover.cover_bonus))
    defender.take_damage(damage)
    return damage


def play_round(side_a, side_b, cover_a, cover_b, log):
    for attacker in [u for u in side_a if u.alive]:
        targets = [u for u in side_b if u.alive]
        if not targets:
            return
        target = random.choice(targets)
        dmg = resolve_attack(attacker, target, cover_b)
        log.append(f"{attacker.name} hits {target.name} for {dmg} "
                   f"(HP left: {target.hp})")


def simulate_battle(turn_order=engage_in_urban_warfare, max_rounds=10):
    player = [Unit("Player Squad 1", 20, 6, 2), Unit("Player Squad 2", 20, 5, 3)]
    enemy = [Unit("AI Squad 1", 20, 6, 2), Unit("AI Squad 2", 20, 5, 3)]
    player_cover = Building("Apartment Block", 1)
    enemy_cover = Building("Warehouse", 2)

    if turn_order == 'First':
        order = [(player, enemy, player_cover, enemy_cover),
                 (enemy, player, enemy_cover, player_cover)]
    elif turn_order == 'Second':
        order = [(enemy, player, enemy_cover, player_cover),
                 (player, enemy, player_cover, enemy_cover)]
    else:
        raise ValueError("turn_order must be 'First' or 'Second'")

    log = []
    for rnd in range(1, max_rounds + 1):
        log.append(f"--- Round {rnd} ---")
        for a, b, ca, cb in order:
            play_round(a, b, ca, cb, log)
        if not any(u.alive for u in player):
            log.append("AI wins.")
            break
        if not any(u.alive for u in enemy):
            log.append("Player wins.")
            break
    else:
        log.append("Stalemate.")
    return log


if __name__ == "__main__":
    for line in simulate_battle():
        print(line)
```

