```python
import random

class Item:
    def __init__(self, name, base_value, stolen=False):
        self.name = name
        self.base_value = base_value
        self.stolen = stolen

class Fence:
    """An in-game NPC who buys stolen items at a discount, with some risk."""
    def __init__(self, discount=0.4, heat_risk=0.15):
        self.discount = discount
        self.heat_risk = heat_risk

    def offer(self, item):
        return int(item.base_value * (1 - self.discount))

def sell_stolen_goods(player, item, fence):
    if not item.stolen:
        return "This item isn't stolen. Sell it at a regular merchant."
    price = fence.offer(item)
    player["gold"] += price
    player["inventory"].remove(item)
    if random.random() < fence.heat_risk:
        player["wanted_level"] += 1
        return f"Sold {item.name} for {price} gold... but the guards noticed. Wanted level: {player['wanted_level']}"
    return f"Sold {item.name} for {price} gold."

# Example
player = {"gold": 0, "inventory": [], "wanted_level": 0}
ring = Item("Silver Ring", 100, stolen=True)
player["inventory"].append(ring)
print(sell_stolen_goods(player, ring, Fence()))
