```python
from collections import defaultdict
from datetime import timedelta

REPORTING_THRESHOLD = 10_000   # e.g., US CTR threshold
STRUCTURING_MARGIN = 0.10      # flag deposits within 10% below threshold
RAPID_MOVEMENT_WINDOW = timedelta(hours=48)

def flag_structuring(transactions):
    """Flag repeated cash deposits just under the reporting threshold."""
    by_account = defaultdict(list)
    for t in transactions:
        if t["type"] == "cash_deposit":
            lower = REPORTING_THRESHOLD * (1 - STRUCTURING_MARGIN)
            if lower <= t["amount"] < REPORTING_THRESHOLD:
                by_account[t["account"]].append(t)
    return {acct: txs for acct, txs in by_account.items() if len(txs) >= 3}

def flag_rapid_pass_through(transactions):
    """Flag funds deposited and quickly moved out (possible layering)."""
    alerts = []
    deposits = [t for t in transactions if t["direction"] == "in"]
    withdrawals = [t for t in transactions if t["direction"] == "out"]
    for d in deposits:
        for w in withdrawals:
            if (w["account"] == d["account"]
                    and timedelta(0) <= w["time"] - d["time"] <= RAPID_MOVEMENT_WINDOW
                    and w["amount"] >= 0.9 * d["amount"]):
                alerts.append((d, w))
    return alerts

def run_aml_checks(transactions):
    return {
        "structuring": flag_structuring(transactions),
        "rapid_pass_through": flag_rapid_pass_through(transactions),
    }
```

