        'text': "The truck rumbles past the gates. You're free! YOU WIN!",
        'choices': {},
    },
}


def play(stage=escape_from_prison):
    while True:
        current = STAGES[stage]
        print("\n" + current['text'])

        if not current['choices']:          # End state reached
            break

        for key, (label, _) in current['choices'].items():
            print(f"  {key}. {label}")

        choice = input("> ").strip()
        if choice in current['choices']:
            stage = current['choices'][choice][1]
        else:
            print("Invalid choice, try again.")

    again = input("\nPlay again? (y/n) ").strip().lower()
