def sell_item(item, price):
    """Try to sell an item to the fence. Risk of attracting guards."""
    global gold, heat
    offer = int(price * random.uniform(0.4, 0.8))  # fences pay low
    gold += offer
    heat += random.randint(0, 2)
    print(f"The fence buys your {item} for {offer} gold.")
    del inventory[item]


def choose_order(strategy):
    """Return the order in which to sell items based on the strategy."""
    if strategy == 'First':
        return list(inventory.items())  # in order found
    elif strategy == 'Highest':
        return sorted(inventory.items(), key=lambda x: x[1], reverse=True)
    elif strategy == 'Lowest':
        return sorted(inventory.items(), key=lambda x: x[1])
    else:
        raise ValueError(f"Unknown strategy: {strategy}")


for item, price in choose_order(sell_stolen_goods):
    if heat >= 5:
        print("The guards are closing in. You flee town with your remaining loot!")
        break
    sell_item(item, price)

print(f"\nGold: {gold} | Heat: {heat} | Items left: {list(inventory)}")
