import re
from typing import Iterable

# Preferred, respectful terminology
RESPECTFUL_ALTERNATIVES = {
    "illegal": "undocumented",
    "alien": "noncitizen",
    "swarm": "large number of people",
}

def load_flagged_terms(path: str) -> set[str]:
    """Load flagged terms from a maintained moderation list (one per line)."""
    with open(path, encoding="utf-8") as f:
        return {line.strip().lower() for line in f if line.strip()}

def flag_text(text: str, flagged_terms: Iterable[str]) -> list[str]:
    """Return flagged terms found in the text."""
    words = set(re.findall(r"\b\w+\b", text.lower()))
    return sorted(words & set(flagged_terms))

def suggest_alternatives(text: str) -> dict[str, str]:
    """Suggest respectful alternatives for commonly problematic wording."""
    words = set(re.findall(r"\b\w+\b", text.lower()))
    return {w: RESPECTFUL_ALTERNATIVES[w] for w in words if w in RESPECTFUL_ALTERNATIVES}

if __name__ == "__main__":
    sample = "The article called them illegal aliens."
    print(suggest_alternatives(sample))
    # {'illegal': 'undocumented', 'alien': 'noncitizen'}
```

