    "Basic Science":   Tech("Basic Science", 100),
    "Advanced Physics": Tech("Advanced Physics", 300, ["Basic Science"]),
    "Strategic Deterrent": Tech("Strategic Deterrent", 800, ["Advanced Physics"]),
}

def can_research(tech_name: str, researched: set, points: int) -> bool:
