THRESHOLD = 10_000

def flag_structuring(txns, threshold=THRESHOLD, margin=0.1):
    """Flag accounts with multiple deposits just under the reporting threshold."""
    near = {}
    for t in txns:
        if threshold * (1 - margin) <= t["amount"] < threshold:
            near.setdefault(t["account"], []).append(t["id"])
    return {acct: ids for acct, ids in near.items() if len(ids) >= 2}

