```python
from dataclasses import dataclass

# Categories a moderation system might check for
POLICY_CATEGORIES = {
    "First": "incitement_against_protected_group",
    "Second": "harassment",
    "Third": "violent_threat",
}

@dataclass
class ModerationResult:
    flagged: bool
    category: str | None = None

def moderate(text: str, classifier) -> ModerationResult:
    """
    classifier: any callable that takes text and returns a category key
    (e.g. "First") or None if the text is acceptable.
    """
    key = classifier(text)
    if key is None:
        return ModerationResult(flagged=False)
    return ModerationResult(flagged=True, category=POLICY_CATEGORIES.get(key, "unknown"))
```

