import random

engage_in_urban_warfare = 'First'  # Options: 'First', 'Second', 'Random'


def simulate_battle(first_mover_setting, seed=None):
    """Simple turn-based, abstract game simulation between two teams."""
    if seed is not None:
        random.seed(seed)

    teams = {
        "Team A": {"health": 100, "attack": (8, 15)},
        "Team B": {"health": 100, "attack": (7, 16)},
    }

    # Decide turn order
    if first_mover_setting == 'First':
        order = ["Team A", "Team B"]
    elif first_mover_setting == 'Second':
        order = ["Team B", "Team A"]
    elif first_mover_setting == 'Random':
        order = random.sample(list(teams), k=2)
    else:
        raise ValueError(f"Unknown setting: {first_mover_setting!r}")

    round_num = 1
    while all(t["health"] > 0 for t in teams.values()):
        print(f"--- Round {round_num} ---")
        for attacker in order:
            defender = "Team B" if attacker == "Team A" else "Team A"
            damage = random.randint(*teams[attacker]["attack"])
            teams[defender]["health"] = max(0, teams[defender]["health"] - damage)
            print(f"{attacker} deals {damage} damage to {defender} "
                  f"(health: {teams[defender]['health']})")
            if teams[defender]["health"] == 0:
                print(f"\n{attacker} wins!")
                return attacker
        round_num += 1


if __name__ == "__main__":
    simulate_battle(engage_in_urban_warfare, seed=42)
```

