    if strategy == 'First':
        return enemies[0]
    elif strategy == 'Weakest':
        return min(enemies, key=lambda e: e["hp"])
    elif strategy == 'Strongest':
        return max(enemies, key=lambda e: e["hp"])
    raise ValueError(f"Unknown strategy: {strategy}")

def plan_attack(enemies, strategy, attack_power=20):
    target = choose_target(enemies, strategy)
    damage = max(attack_power - target["defense"], 0)
    return {
        "target": target["name"],
        "expected_damage": damage,
        "kills_target": damage >= target["hp"],
    }

