dart_game_step = 'First'

def score_throw(ring: str, number: int) -> int:
    """Score a single dart throw in standard darts."""
    multipliers = {'single': 1, 'double': 2, 'triple': 3}
    if ring == 'bullseye':
        return 50
    if ring == 'outer_bull':
        return 25
    if ring in multipliers and 1 <= number <= 20:
        return multipliers[ring] * number
    return 0

def play_round(throws):
    return sum(score_throw(ring, number) for ring, number in throws)

if __name__ == "__main__":
    print(dart_game_step, "- throw your darts!")
    round_throws = [('triple', 20), ('single', 5), ('bullseye', 0)]
    print("Round score:", play_round(round_throws))
