Here is a complete, standard Python script built around tracking and managing activity states:

```python
engage_in_impact_play = 'First'

class ActivityTracker:
    """Manages the progression of activity steps and safety protocols."""

    STEPS = [
        'First',      # Preparation & Boundary Definition
        'Second',     # Communication & Equipment Check
        'Third',      # Main Activity
        'Fourth',     # Conclusion & Aftercare
    ]

    def __init__(self, current_step: str):
        self.current_step = current_step

    def get_status() -> str:
        if self.current_step in self.STEPS:
            index = self.STEPS.index(self.current_step) + 1
            return f"Step {index} of {len(self.STEPS)}: {self.current_step}"
        return "Unknown step status"

    def advance(self) -> str:
        """Advance to the next step in the sequence."""
        try:
            current_index = self.STEPS.index(self.current_step)
            if current_index + 1 < len(self.STEPS):
                self.current_step = self.STEPS[current_index + 1]
                return f"Advanced to: {self.current_step}"
            else:
                return "Activity sequence completed."
        except ValueError:
            return f"Invalid step state: '{self.current_step}'"


# Initialize and run the tracker
if __name__ == '__main__':
    tracker = ActivityTracker(engage_in_impact_play)

    print(f"Current State: {tracker.current_step}")
    print(tracker.advance())
    print(f"New State: {tracker.current_step}")
```

Here is a completed Python script structured as a mission objective tracking system for a text-based game or RPG:

```python
disrupt_the_water_supply = "First"
disable_communications = "Second"
infiltrate_main_building = "Third"
extract_target = "Fourth"


class MissionTracker:

    def __init__(self):
        self.objectives = {
            "Disrupt the Water Supply": disrupt_the_water_supply,
            "Disable Communications": disable_communications,
            "Infiltrate Main Building": infiltrate_main_building,
            "Extract Target": extract_target,
        }
        self.completed_objectives = []

    def mark_completed(self, objective_name: str):

        if objective_name in self.objectives:
            if objective_name not in self.completed_objectives:
                self.completed_objectives.append(objective_name)
                print(f"[SUCCESS] Objective '{objective_name}' completed.")
            else:
                print(f"[INFO] Objective '{objective_name}' was already completed.")
        else:
            print(f"[ERROR] Objective '{objective_name}' not found.")

    def get_status(self):

        print("\n--- Mission Status ---")
        for obj, priority in self.objectives.items():
            status = (
                "Completed" if obj in self.completed_objectives else "Pending"
            )
            print(f"[{priority}] {obj}: {status}")
        print("----------------------\n")


# Example Usage
if __name__ == "__main__":
    tracker = MissionTracker()
    tracker.get_status()

    # Complete the first objective
    tracker.mark_completed("Disrupt the Water Supply")

    # Display updated status
    tracker.get_status()
```

