        self.account_holder = account_holder
        self._balance = initial_balance  # Encapsulated balance

    def deposit(self, amount: float) -> None:
        """Deposits a positive amount into the bank account."""
        if amount > 0:
            self._balance += amount
            print(f"Successfully deposited ${amount:.2f}. New balance: ${self._balance:.2f}")
        else:
            print("Deposit amount must be greater than zero.")

    def withdraw(self, amount: float) -> None:
        """Withdraws an amount from the bank account if sufficient funds exist."""
        if amount <= 0:
