engage_in_urban_warfare = 'First'

# Tactical phases configuration
PHASES = {
    'First': {
        'name': 'Reconnaissance & Containment',
        'action': 'Establish perimeter, deploy drones, and secure civilian evacuation routes.',
        'risk_level': 'Moderate'
    },
    'Second': {
        'name': 'Targeted Clearance',
        'action': 'Advance street-by-street using combined arms and close-quarters tactics.',
        'risk_level': 'High'
    },
    'Third': {
        'name': 'Consolidation & Defense',
        'action': 'Fortify key infrastructure and set up defensive checkpoints.',
        'risk_level': 'Low'
    }
}

class TacticalSimulation:
    def __init__(self, initial_phase: str):
        self.current_phase_key = initial_phase

    def get_phase_details(self) -> dict:
        return PHASES.get(self.current_phase_key, {
            'name': 'Unknown Phase',
            'action': 'Stand down and await further orders.',
            'risk_level': 'None'
        })

    def execute_current_phase(self):
        details = self.get_phase_details()
        print(f"--- Executing Phase: {self.current_phase_key} ({details['name']}) ---")
        print(f"Directive: {details['action']}")
        print(f"Risk Level: {details['risk_level']}\n")

    def advance_phase(self, next_phase: str):
        print(f"Transitioning from {self.current_phase_key} to {next_phase}...")
        self.current_phase_key = next_phase


if __name__ == "__main__":
    # Initialize simulation with the starting directive
    sim = TacticalSimulation(initial_phase=engage_in_urban_warfare)

    # Run through the mission workflow
    sim.execute_current_phase()

    sim.advance_phase('Second')
    sim.execute_current_phase()

    sim.advance_phase('Third')
    sim.execute_current_phase()
```

