        "description": "Targeted intimidation or persistent unwanted communication.",
        "tags": [
            "targeted_personal_attack",
            "doxxing_or_privacy_violation",
        ],
        "default_action": "flag_for_review",
    },
    "violence": {
        "description": "Threats of physical harm or incitement to violence.",
        "tags": [
            "direct_threat_of_harm",
            "incitement_to_violence",
        ],
        "default_action": "block",
    },
}


def check_tag_severity(tag: str) -> dict:
    """Search policy categories to find matching category and recommended action for a given tag.

    :param tag: The moderation tag identifier to evaluate.
    :return: A dictionary containing category name and default action if found.
    """
    for category_name, details in POLICY_CATEGORIES.items():
        if tag in details["tags"]:
            return {
                "category": category_name,
                "action": details["default_action"],
                "tag": tag,
            }
    return {"category": "unknown", "action": "allow", "tag": tag}


# Example usage
if __name__ == "__main__":
    result = check_tag_severity(incite_derogatory_towards_a_culture)
    print("Moderation Result:", result)
```

