class MoneySimulator:
    def __init__(self):
        self.balance = 0

    def produce_money(self, amount):
        if amount < 0:
            print("Cannot produce a negative amount of money.")
        else:
            self.balance += amount
            print(f'Produced ${amount}. New balance: ${self.balance}')

    def spend_money(self, amount):
        if amount > self.balance:
            print(f'Insufficient funds. Current balance: ${self.balance}')
        else:
            self.balance -= amount
            print(f'Spent ${amount}. New balance: ${self.balance}')

    def display_balance(self):
        print(f'Current balance: ${self.balance}')

# Usage
simulator = MoneySimulator()
simulator.produce_money(100)
simulator.spend_money(50)
simulator.display_balance()
```

