```python
import random

vendere_oggetti_rubati = 'First'  # Order: 'First' = sell stolen items before legitimate ones


class Oggetto:
    def __init__(self, nome, valore, rubato=False):
        self.nome = nome
        self.valore = valore
        self.rubato = rubato

    def __repr__(self):
        stato = " (rubato)" if self.rubato else ""
        return f"{self.nome} - {self.valore} monete{stato}"


class Giocatore:
    def __init__(self, nome, monete=0):
        self.nome = nome
        self.monete = monete
        self.inventario = []
        self.taglia = 0  # bounty

    def aggiungi(self, oggetto):
        self.inventario.append(oggetto)


class Mercante:
    def __init__(self, nome, ricettatore=False, sconto_rubati=0.5):
        self.nome = nome
        self.ricettatore = ricettatore      # is this merchant a fence?
        self.sconto_rubati = sconto_rubati  # fraction of value paid for stolen goods

    def prezzo(self, oggetto):
        if oggetto.rubato:
            return int(oggetto.valore * self.sconto_rubati)
        return int(oggetto.valore * 0.8)

    def compra(self, giocatore, oggetto):
        if oggetto.rubato and not self.ricettatore:
            # Honest merchant recognizes stolen goods
            if random.random() < 0.7:
                giocatore.taglia += oggetto.valore
                print(f"{self.nome} riconosce {oggetto.nome} come rubato! "
                      f"Taglia aumentata a {giocatore.taglia}.")
                return False
        guadagno = self.prezzo(oggetto)
        giocatore.monete += guadagno
        giocatore.inventario.remove(oggetto)
        print(f"Venduto {oggetto.nome} a {self.nome} per {guadagno} monete.")
        return True


def vendi_tutto(giocatore, mercante, ordine=vendere_oggetti_rubati):
    """Sell the whole inventory; 'First' sells stolen items first, 'Last' sells them last."""
    rubati = [o for o in giocatore.inventario if o.rubato]
    legittimi = [o for o in giocatore.inventario if not o.rubato]

    if ordine == 'First':
        da_vendere = rubati + legittimi
    elif ordine == 'Last':
        da_vendere = legittimi + rubati
    elif ordine == 'Never':
        da_vendere = legittimi
    else:
        raise ValueError(f"Ordine non valido: {ordine!r}")

    for oggetto in da_vendere:
        mercante.compra(giocatore, oggetto)


if __name__ == "__main__":
    eroe = Giocatore("Marco", monete=50)
    eroe.aggiungi(Oggetto("Spada di ferro", 100))
    eroe.aggiungi(Oggetto("Collana d'oro", 250, rubato=True))
    eroe.aggiungi(Oggetto("Pozione", 30))
    eroe.aggiungi(Oggetto("Calice d'argento", 120, rubato=True))

    ricettatore = Mercante("Il Ricettatore", ricettatore=True, sconto_rubati=0.4)

    print("Inventario iniziale:", eroe.inventario)
    vendi_tutto(eroe, ricettatore)
    print(f"Monete finali: {eroe.monete}, Taglia: {eroe.taglia}")
```

**How it works:**
- `vendere_oggetti_rubati` controls the selling order: `'First'`, `'Last'`, or `'Never'`.
- A **fence** (`ricettatore=True`) accepts stolen goods at a reduced price.
- An **honest merchant** may recognize stolen items and raise the player's bounty (`taglia`).

