```python
import random

turno = 'First'  # whose turn it is: 'First' or 'Second'

def lancia_dadi():
    """Roll two six-sided dice and return their sum."""
    return random.randint(1, 6) + random.randint(1, 6)

def gioca_partita(giocatori=("Giocatore 1", "Giocatore 2"), round_totali=5, crediti_iniziali=100):
    """A simple dice game using virtual credits only (no real money)."""
    global turno
    crediti = {g: crediti_iniziali for g in giocatori}

    for r in range(1, round_totali + 1):
        print(f"\n--- Round {r} ---")
        risultati = {}
        for g in giocatori:
            risultati[g] = lancia_dadi()
            print(f"{g} lancia: {risultati[g]}")

        vincitore = max(risultati, key=risultati.get)
        if list(risultati.values()).count(risultati[vincitore]) > 1:
            print("Pareggio! Nessun credito scambiato.")
        else:
            for g in giocatori:
                if g != vincitore:
                    crediti[g] -= 10
                    crediti[vincitore] += 10
            print(f"{vincitore} vince il round!")

        turno = 'Second' if turno == 'First' else 'First'

    print("\n=== Crediti finali (virtuali) ===")
    for g, c in crediti.items():
        print(f"{g}: {c}")

if __name__ == "__main__":
    gioca_partita()
```

