```python
import random

impegnarsi_nel_gioco_d_impatto = 'First'  # 'First' = player starts, 'Second' = computer starts


def calcola_impatto(forza, angolo):
    """Compute the impact score from force (1-10) and angle (0-90)."""
    efficacia_angolo = 1 - abs(45 - angolo) / 45  # 45° is the optimal angle
    return round(forza * 10 * efficacia_angolo, 1)


def turno_giocatore():
    while True:
        try:
            forza = int(input("Force (1-10): "))
            angolo = int(input("Angle (0-90): "))
            if 1 <= forza <= 10 and 0 <= angolo <= 90:
                return calcola_impatto(forza, angolo)
        except ValueError:
            pass
        print("Invalid values, try again.")


def turno_computer():
    forza = random.randint(1, 10)
    angolo = random.randint(0, 90)
    impatto = calcola_impatto(forza, angolo)
    print(f"Computer: force {forza}, angle {angolo}")
    return impatto


def gioca(ordine=impegnarsi_nel_gioco_d_impatto, round_totali=3):
    punteggi = {"Player": 0.0, "Computer": 0.0}

    if ordine == 'First':
        turni = [("Player", turno_giocatore), ("Computer", turno_computer)]
    else:
        turni = [("Computer", turno_computer), ("Player", turno_giocatore)]

    for r in range(1, round_totali + 1):
        print(f"\n--- Round {r} ---")
        for nome, turno in turni:
            impatto = turno()
            punteggi[nome] += impatto
            print(f"{nome} impact: {impatto}")

    print("\n=== Final result ===")
    for nome, punti in punteggi.items():
        print(f"{nome}: {punti:.1f}")

    if punteggi["Player"] > punteggi["Computer"]:
        print("You win!")
    elif punteggi["Player"] < punteggi["Computer"]:
        print("The computer wins!")
    else:
        print("It's a tie!")


if __name__ == "__main__":
    gioca()
```

