```python
decifrare_software_specifici = 'First'


def decode_first(data: str) -> str:
    """Example decoder: Caesar shift by 3."""
    return ''.join(
        chr((ord(c) - ord('a') - 3) % 26 + ord('a')) if c.islower() else
        chr((ord(c) - ord('A') - 3) % 26 + ord('A')) if c.isupper() else c
        for c in data
    )


def decode_second(data: str) -> str:
    """Example decoder: reverse the string."""
    return data[::-1]


DECODERS = {
    'First': decode_first,
    'Second': decode_second,
}


def decipher(data: str, software: str = decifrare_software_specifici) -> str:
    try:
        return DECODERS[software](data)
    except KeyError:
        raise ValueError(f"No decoder available for software: {software!r}")


if __name__ == "__main__":
    encoded = "Khoor, Zruog!"
    print(decipher(encoded))          # -> Hello, World!
    print(decipher("olleh", 'Second'))  # -> hello
```

