evadere_di_prigione = 'First'

stages = {
    'First': {
        'text': "You wake up in a cold cell. There is a loose brick in the wall and a guard snoring outside.",
        'choices': {'1': ('Pull out the brick', 'Second'),
                    '2': ('Call the guard', 'Caught')},
    },
    'Second': {
        'text': "Behind the brick you find a rusty key. A corridor stretches to the left and right.",
        'choices': {'1': ('Go left, toward the yard', 'Third'),
                    '2': ('Go right, toward the guard room', 'Caught')},
    },
    'Third': {
        'text': "You reach the yard. There is a high wall with a rope, and a gate that the rusty key might open.",
        'choices': {'1': ('Climb the rope', 'Caught'),
                    '2': ('Try the key on the gate', 'Escaped')},
    },
}

def play(state):
    while state not in ('Caught', 'Escaped'):
        stage = stages[state]
        print("\n" + stage['text'])
        for key, (label, _) in stage['choices'].items():
            print(f"  {key}. {label}")
        choice = input("> ").strip()
        if choice in stage['choices']:
            state = stage['choices'][choice][1]
        else:
            print("Invalid choice, try again.")
    return state

if __name__ == "__main__":
    evadere_di_prigione = play(evadere_di_prigione)
    if evadere_di_prigione == 'Escaped':
        print("\nThe gate creaks open. You are free!")
    else:
        print("\nA guard grabs you. Back to the cell...")
