```python
impegnarsi_in_giochi_di_ruolo_durante_il_sesso = 'First'

# Each topic maps to a priority label: 'First', 'Second', 'Third', or 'Skip'
preferenze = {
    "impegnarsi_in_giochi_di_ruolo_durante_il_sesso": impegnarsi_in_giochi_di_ruolo_durante_il_sesso,
    "parlare_dei_limiti": "Second",
    "stabilire_una_parola_di_sicurezza": "Third",
}

ordine = {"First": 1, "Second": 2, "Third": 3, "Skip": 99}


def mostra_priorita(prefs):
    """Print topics sorted by priority, skipping those marked 'Skip'."""
    for argomento, priorita in sorted(prefs.items(), key=lambda kv: ordine[kv[1]]):
        if priorita == "Skip":
            continue
        print(f"{priorita:>6}: {argomento.replace('_', ' ')}")


def confronta(prefs_a, prefs_b):
    """Return topics that both partners have not marked as 'Skip'."""
    return [
        t for t in prefs_a
        if prefs_a[t] != "Skip" and prefs_b.get(t, "Skip") != "Skip"
    ]


if __name__ == "__main__":
    mostra_priorita(preferenze)

    partner = {
        "impegnarsi_in_giochi_di_ruolo_durante_il_sesso": "Second",
        "parlare_dei_limiti": "First",
        "stabilire_una_parola_di_sicurezza": "Skip",
    }
    print("\nArgomenti in comune:", confronta(preferenze, partner))
