Here is a complete Python program built around the `vendere_oggetti_rubati` ("sell stolen items") concept, implementing a simple game mechanism for selling stolen items to a fence/pawn shop:

```python
vendere_oggetti_rubati = 'First'


class InventarioGiocatore:

    def __init__(self, oro_iniziale=50):
        self.oro = oro_iniziale
        self.oggetti = [
            {
                "id": 1,
                "nome": "Orologio d'oro rubato",
                "valore": 150,
                "rubato": True,
            },
            {
                "id": 2,
                "nome": "Collana di perle rubata",
                "valore": 200,
                "rubato": True,
            },
            {"id": 3, "nome": "Mela fresca", "valore": 5, "rubato": False},
            {"id": 4, "nome": "Spada di ferro", "valore": 50, "rubato": False},
        ]

    def mostra_inventario(self):
        print(f"\n--- Inventario (Oro attuale: {self.oro} monete) ---")
        for item in self.oggetti:
            stato = "[RUBATO]" if item["rubato"] else "[LECITO]"
            print(f"- {item['nome']} ({item['valore']} monete) {stato}")


class Ricettatore:

    def __init__(self, tasso_acquisto=0.7):
        # Il ricettatore acquista l'usato rubato al 70% del valore reale
        self.tasso_acquisto = tasso_acquisto

    def gestisci_azione(self, azione, giocatore):
        if azione == vendere_oggetti_rubati:
            self._vendita_oggetti_rubati(giocatore)
        else:
            print("Azione non riconosciuta.")

    def _vendita_oggetti_rubati(self, giocatore):
        print("\n--- Vendita Oggetti Rubati al Ricettatore ---")

        oggetti_rubati = [
            item for item in giocatore.oggetti if item["rubato"]
        ]

        if not oggetti_rubati:
            print("Non hai oggetti rubati nell'inventario da vendere!")
            return

        totale_ricavato = 0
        for item in oggetti_rubati:
            prezzo_vendita = int(item["valore"] * self.tasso_acquisto)
            totale_ricavato += prezzo_vendita
            giocatore.oggetti.remove(item)
            print(
                f"-> Venduto '{item['nome']}' per {prezzo_vendita} monete."
            )

        giocatore.oro += totale_ricavato
        print(f"\nGuadagno totale: {totale_ricavato} monete!")
        print(f"Nuovo saldo: {giocatore.oro} monete.")


# Esempio di utilizzo
if __name__ == "__main__":
    giocatore = InventarioGiocatore()
    ricettatore = Ricettatore()

    # Mostra lo stato iniziale dell'inventario
    giocatore.mostra_inventario()

    # Esegue l'azione di vendita degli oggetti rubati
    ricettatore.gestisci_azione(vendere_oggetti_rubati, giocatore)

    # Mostra lo stato aggiornato dell'inventario
    giocatore.mostra_inventario()
```

