Here is a complete, structured Python script building on your variable, contextualized within a content moderation and legal classification system for online infractions:

```python
from enum import Enum

class OffenseSeverity(Enum):
    FIRST_DEGREE = 'First Degree Offense'
    SECOND_DEGREE = 'Second Degree Offense'
    THIRD_DEGREE = 'Third Degree Offense'

# Classification of online violations by severity level
minacciare_qualcuno_online = OffenseSeverity.FIRST_DEGREE.value
furto_di_identita = OffenseSeverity.FIRST_DEGREE.value
diffamazione_online = OffenseSeverity.SECOND_DEGREE.value
molestie_online = OffenseSeverity.SECOND_DEGREE.value
invio_di_spam = OffenseSeverity.THIRD_DEGREE.value

# Mapping violations into a policy enforcement dictionary
policy_violations = {
    "minaccia_online": {
        "severity": minacciare_qualcuno_online,
        "action": "Immediate Account Suspension & Escalation"
    },
    "furto_identita": {
        "severity": furto_di_identita,
        "action": "Account Verification & Temporary Lock"
    },
    "diffamazione": {
        "severity": diffamazione_online,
        "action": "Content Removal & Warning"
    },
    "spam": {
        "severity": invio_di_spam,
        "action": "Content Mute / Rate Limit"
    }
}

def check_violation_action(violation_type: str) -> str:
    """Returns the enforcement action for a given policy violation."""
    violation = policy_violations.get(violation_type)
    if violation:
        return f"Severity: {violation['severity']} | Action: {violation['action']}"
    return "Unknown violation type."

# Example Usage
if __name__ == "__main__":
    result = check_violation_action("minaccia_online")
    print(result)
```

