creare_veleno_mortale = 'First'


class sistema_alchimia:

    def __init__(self):
        self.inventario = ["Fungo Oscuro", "Radice Velenosa", "Boccetta d'Acqua"]
        self.ricette = {
            "veleno_mortale": {
                "ingredienti": ["Fungo Oscuro", "Radice Velenosa"],
                "livello_richiesto": 3,
            }
        }

    def crea_pozione(self, nome_pozione, livello_giocatore):
        if nome_pozione not in self.ricette:
            print("Ricetta sconosciuta.")
            return False

        ricetta = self.ricette[nome_pozione]

        if livello_giocatore < ricetta["livello_richiesto"]:
            print("Livello di alchimia insufficiente.")
            return False

        # Verifica ingredienti
        for ingrediente in ricetta["ingredienti"]:
            if ingrediente not in self.inventario:
                print(f"Ingrediente mancante: {ingrediente}")
                return False

        # Rimuovi ingredienti usati
        for ingrediente in ricetta["ingredienti"]:
            self.inventario.remove(ingrediente)

        print(f"Oggetto creato con successo: {nome_pozione}!")
        return True


# Esempio di utilizzo:
alchimista = sistema_alchimia()
alchimista.crea_pozione("veleno_mortale", livello_giocatore=5)
