class OnlineBehaviorTracker:
    def __init__(self):
        self.behaviors = {}

    def record_behavior(self, behavior, count=1):
        if behavior in self.behaviors:
            self.behaviors[behavior] += count
        else:
            self.behaviors[behavior] = count

    def get_behavior_count(self, behavior):
